struct Snapshot {
  static constexpr MsgId kId = MsgId::Snapshot;
  static constexpr std::uint8_t kChannel = 1;
  static constexpr Direction kDirection = Direction::ServerToClient;
  static constexpr const char* kName = "Snapshot";
  std::uint32_t server_tick{};
  std::uint32_t ack_seq{};
  float self_x{};
  float self_y{};
  float self_z{};
  std::vector<EntityState> entities;
  void encode(Writer& w) const {
    w.u32(server_tick);
    w.u32(ack_seq);
    w.f32(self_x);
    w.f32(self_y);
    w.f32(self_z);
    { const std::size_t count = std::min<std::size_t>(entities.size(), 256);
      w.u16(static_cast<std::uint16_t>(count));
      for (std::size_t i = 0; i < count; ++i) {
        entities[i].encode(w);
      }
    }
  }
  bool decode(Reader& r) {
    if (!r.u32(server_tick)) return false;
    if (!r.u32(ack_seq)) return false;
    if (!r.f32(self_x)) return false;
    if (!r.f32(self_y)) return false;
    if (!r.f32(self_z)) return false;
    { std::uint16_t count = 0;
      if (!r.u16(count) || count > 256) return r.fail();
      entities.clear();
      entities.reserve(count);
      for (std::uint16_t i = 0; i < count; ++i) {
        EntityState v;
        if (!v.decode(r)) return false;
        entities.push_back(v);
      }
    }
    return true;
  }
};

